var pageStyles = `
:root { color-scheme: light dark; font: 15px/1.6 -apple-system,BlinkMacSystemFont,"PingFang SC","Microsoft YaHei",sans-serif;
  color: light-dark(#1a2520,#edf1ed); background: light-dark(#f7f8f6,#171c19);
  --surface: light-dark(#fff,#202723); --inset: light-dark(#f2f4f1,#2a332d); --line: light-dark(#dce3dc,#39453d);
  --secondary: light-dark(#56665c,#b2c0b6); --focus: light-dark(#176448,#a7d9b8); }
* { box-sizing: border-box; }
body { margin: 0; }
main { width: min(42rem,calc(100% - 32px)); margin: clamp(24px,8vh,80px) auto;
  padding: clamp(18px,4vw,32px); border: 1px solid var(--line); border-radius: 12px; background: var(--surface); }
.brand { height:61px; display:flex; align-items:center; gap:10px; padding:0 5%; background:var(--surface); font-size:19px; font-weight:700; border-bottom:1px solid var(--line); }
.brand svg { width:30px; height:30px; }
h1 { margin: 22px 0 10px; font-size: 1.65rem; line-height: 1.3; letter-spacing: -.5px; }
h2 { font-size: 1.13rem; margin: 26px 0 8px; }
p { margin: 8px 0 14px; overflow-wrap: anywhere; }
main > :last-child { margin-bottom: 0; }
form + h2 { padding-top: 20px; border-top: 1px solid var(--line); }
label { display: grid; gap: 4px; font-weight: 550; }
input,textarea,pre,button { font: inherit; border: 1px solid var(--line); border-radius: 7px; padding: 8px 10px; }
input,textarea { width: 100%; color: inherit; background: var(--inset); }
pre,textarea,code,dd { overflow-wrap: anywhere; }
pre,textarea { font: 13px/1.65 ui-monospace,SFMono-Regular,Consolas,monospace; white-space: pre-wrap; background: var(--inset); }
#command { display: block; field-sizing: content; min-height: 4.75em; resize: vertical; }
#copy { width: 100%; min-height: 44px; margin-top: 10px; }
#copy-status:not(:empty) { display: block; margin-top: 6px; color: var(--secondary); font-size: 13px; }
button { cursor: pointer; color: inherit; background: var(--inset); }
button:hover { border-color: var(--secondary); }
.strong { color: white; background: #164e40; border-color: #164e40; }
.strong:hover { background: #103e32; }
button[value="disable"] { color: light-dark(#a41e27,#ff9599); background: light-dark(#f9dfe0,#412426); border-color: transparent; }
button[value="disable"]:hover { border-color: currentColor; }
a { color: var(--focus); text-underline-offset: 3px; }
:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
dl { display: grid; grid-template-columns: minmax(6rem, 36%) minmax(0,1fr); margin: 16px 0; }
dt,dd { margin: 0; padding: 9px 0; border-top: 1px solid var(--line); }
dt { color: var(--secondary); padding-right: 12px; }
main.result:not(:has(form,pre,dl,textarea)) { text-align:center; padding-block:44px; }
main.result:not(:has(form,pre,dl,textarea)) a,.ticket-back a { display:inline-block; padding:8px 14px; border-radius:7px; background:#164e40; color:white; text-decoration:none; }
main:has(.sheet) { width:min(720px,calc(100% - 32px)); padding:0; border:0; background:none; margin:45px auto; }
.sheet { padding:22px 26px; background:var(--surface); border:1px solid var(--line); border-radius:13px; margin:20px 0; }
.sheet h2:first-child { margin:0; }.sheet input { background:var(--surface); }
.receipt { padding:0; overflow:hidden; }.receipt header { padding:28px 24px; text-align:center; background:var(--inset); }.receipt h1 {margin:0 0 4px}
.receipt.success header { background:#146b4b; color:white; }.receipt section{padding:20px 26px}.receipt section h2{margin-top:0}
.ticket-command { background:#192421; color:#cfebd8; padding:16px; }.ticket-value { user-select:all; }
`;
